import re

SPECS = [
    ("dg", "disk_groups", ["NAME", "NCONFIG", "NLOG", "MINORS", "GROUP-ID"]),
    ("st", "site", ["NAME", "STATE", "DM_CNT", "SPARE_CNT", "APPVOL_CNT"]),
    ("dm", "disks", ["NAME", "DEVICE", "TYPE", "PRIVLEN", "PUBLEN", "STATE"]),
    ("rv", "rvgs", ["NAME", "RLINK_CNT", "KSTATE", "STATE", "PRIMARY", "DATAVOLS", "SRL"]),
    ("rl", "rlinks", ["NAME", "RVG", "KSTATE", "STATE", "REM_HOST", "REM_DG", "REM_RLNK"]),
    ("co", "caches", ["NAME", "CACHEVOL", "KSTATE", "STATE"]),
    ("vt", "volume_sets", ["NAME", "RVG", "KSTATE", "STATE", "NVOLUME"]),
    ("v", "volumes", ["NAME", "RVG/VSET/CO", "KSTATE", "STATE", "LENGTH", "READPOL", "PREFPLEX", "UTYPE"]),
    ("pl", "plexes", ["NAME", "VOLUME", "KSTATE", "STATE", "LENGTH", "LAYOUT", "NCOL/WID", "MODE"]),
    ("sd", "subdisks", ["NAME", "PLEX", "DISK", "DISKOFFS", "LENGTH", "[COL/]OFF", "DEVICE", "MODE"]),
    ("sv", "subvolumes", ["NAME", "PLEX", "VOLNAME", "NVOLLAYR", "LENGTH", "[COL/]OFF", "AM/NM", "MODE"]),
    ("sc", "subcaches", ["NAME", "PLEX", "CACHE", "DISKOFFS", "LENGTH", "[COL/]OFF", "DEVICE", "MODE"]),
    ("dc", "dcos", ["NAME", "PARENTVOL", "LOGVOL"]),
    ("sp", "snap_points", ["NAME", "SNAPVOL", "DCO"]),
    ("ex", "exports", ["NAME", "ASSOC", "VC", "PERMS", "MODE", "STATE"]),
    ("sr", "sr", ["NAME", "KSTATE"]),
]

def parse(lines):
    spec = {}
    for p, n, c in SPECS:
        spec[p] = (n, c)
    tables = {}
    order = []
    kv = {"name": "disk_group_title", "kind": "kv", "lines": [], "records": []}
    skip = []
    dg = ""
    for i, raw in enumerate(lines):
        s = raw.strip()
        if not s:
            continue
        if s.startswith("#") or re.match(r"^[A-Z]{1,2}\s+NAME(\s|$)", raw):
            skip.append(i)
            continue
        m = re.match(r"^Disk group:\s*(\S+)\s*$", raw)
        if m:
            dg = m.group(1)
            kv["lines"].append(i)
            kv["records"].append({"Disk group": dg})
            continue
        toks = s.split()
        if toks[0] not in spec:
            continue
        name, cols = spec[toks[0]]
        vals = toks[1:]
        if len(vals) > len(cols):
            vals = vals[:len(cols) - 1] + [" ".join(vals[len(cols) - 1:])]
        vals = vals + [""] * (len(cols) - len(vals))
        rec = {"disk_group": dg}
        for c, v in zip(cols, vals):
            rec[c] = v
        if name not in tables:
            tables[name] = {"name": name, "kind": "table", "lines": [], "records": []}
            order.append(name)
        tables[name]["lines"].append(i)
        tables[name]["records"].append(rec)
    blocks = []
    if kv["records"]:
        blocks.append(kv)
    for n in order:
        blocks.append(tables[n])
    return {"blocks": blocks, "skip": skip}
